```javascript
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, fract, sin, dot, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, AmbientLight, DirectionalLight } = ctx.THREE;

  const group = new Group();
  const timelines = [];

  // 1. STAGE / BACKDROP (Prevents FLAT_VOID defect)
  // Stage gradient shader using spec colors: surface (#0b0b10) to ink (#16161d)
  const backdropGeo = new PlaneGeometry(12, 9);
  const backdropMat = new MeshBasicNodeMaterial();

  const backdropUv = uv();
  const bgGradient = mix(
    vec3(0.043, 0.043, 0.063), // #0b0b10 (surface)
    vec3(0.086, 0.086, 0.114), // #16161d (ink)
    backdropUv.y
  );

  // Add extremely subtle signal red (#ff2a38) vignette glow from bottom-left
  const glowCenter = vec2(0.1, 0.1);
  const dist = backdropUv.distance(glowCenter);
  const glow = mix(vec3(1.0, 0.16, 0.22).mul(0.08), vec3(0.0), dist.clamp(0.0, 1.0));

  backdropMat.colorNode = vec4(bgGradient.add(glow), 1.0);

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -1.5);
  group.add(backdropMesh);

  // 2. LIGHTING CONFIGURATION (Studio product shot style)
  const ambientLight = new AmbientLight(0xffffff, 0.4);
  group.add(ambientLight);

  // Key light matching the "signal red" accent hue slightly
  const keyLight = new DirectionalLight(0xff2a38, 1.2);
  keyLight.position.set(3, 4, 3);
  group.add(keyLight);

  // Cool rim fill light matching paper/ink mix
  const rimLight = new DirectionalLight(0xe8ecf2, 0.8);
  rimLight.position.set(-4, -2, 2);
  group.add(rimLight);

  // 3. JOURNAL CARD STRUCTURE (Machined-metal appearance)
  const cardGroup = new Group();
  group.add(cardGroup);

  // Card Outer Bezel/Shadow Plain (Contact Shadow)
  const shadowGeo = new PlaneGeometry(3.6, 2.4);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.5 });
  const shadowUv = uv();
  const shadowMap = mix(vec3(0.0), vec3(0.1, 0.1, 0.1), shadowUv.y);
  shadowMat.colorNode = vec4(shadowMap, mix(0.5, 0.0, shadowUv.distance(0.5).mul(2.0)));
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0.05, -0.05, -0.05);
  cardGroup.add(shadowMesh);

  // Main Card Body (Machined-Metal Outer Frame)
  const frameGeo = new PlaneGeometry(3.4, 2.2);
  const frameMat = new MeshStandardNodeMaterial({
    color: 0x16161d, // ink
    roughness: 0.52,
    metalness: 0.55,
    clearcoat: 0.2
  });
  const frameMesh = new Mesh(frameGeo, frameMat);
  cardGroup.add(frameMesh);

  // Inner Image Container Plane
  const imageGeo = new PlaneGeometry(3.2, 2.0);
  const imageMat = new MeshBasicNodeMaterial({
    color: 0x0b0b10, // Default dark surface until map loads
    transparent: true
  });

  // Custom subtle grain shader overlay blended onto static color
  const imgUv = uv();
  const grain = fract(sin(dot(imgUv.mul(300.0), vec2(12.9898, 78.233))).mul(43758.5453)).mul(0.05);
  imageMat.colorNode = vec4(vec3(0.043, 0.043, 0.063).add(grain), 1.0);

  const imageMesh = new Mesh(imageGeo, imageMat);
  imageMesh.position.set(0, 0, 0.01);
  cardGroup.add(imageMesh);

  // Accent edge lines (Top and Left red signal striping)
  const accentRedGeo = new PlaneGeometry(3.2, 0.015);
  const accentRedMat = new MeshBasicNodeMaterial({ color: 0xff2a38 });
  const accentRedMesh = new Mesh(accentRedGeo, accentRedMat);
  accentRedMesh.position.set(0, 0.99, 0.015);
  cardGroup.add(accentRedMesh);

  // Load Main Visual Asset
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      // Once loaded, swap dynamic TSL mapping to showcase the asset beautifully
      const texNode = texture;
      imageMat.colorNode = null; // Revert to standard map usage
      imageMat.map = texNode;
      imageMat.needsUpdate = true;
    }).catch((err) => {
      console.warn("Failed loading journal asset, defaulting to engineered gradient fallback.", err);
    });
  }

  // 4. ANIMATION VOCABULARY (Rise-in & weighted-settle on load)
  cardGroup.position.set(0, -0.4, 0.2);
  cardGroup.scale.set(0.95, 0.95, 0.95);
  cardGroup.rotation.set(0.05, -0.05, 0);

  const introTimeline = gsap.timeline();
  timelines.push(introTimeline);

  introTimeline.to(cardGroup.position, {
    y: 0,
    z: 0.0,
    duration: 0.9,
    ease: "power4.out"
  });

  introTimeline.to(cardGroup.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 1.1,
    ease: "back.out(1.2)"
  }, "<");

  introTimeline.to(cardGroup.rotation, {
    x: 0,
    y: 0,
    duration: 0.8,
    ease: "power3.out"
  }, "<");

  // 5. CLEANUP HANDLER
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    backdropGeo.dispose();
    backdropMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    imageGeo.dispose();
    imageMat.dispose();
    accentRedGeo.dispose();
    accentRedMat.dispose();
  };

  return group;
}
